"use client";

/**
 * The live process panel: Show process / Hide process.
 *
 * What it renders is what the backend PERSISTED. There is no timer that
 * advances a step because time passed, and no stage drawn as complete
 * because a later one started. A future step is drawn as plainly
 * prospective -- an empty circle and muted text -- because a checkmark on
 * something that has not happened is a lie the user cannot detect.
 *
 * Accessibility: the collapsed line is a real button with aria-expanded; the
 * live region announces the STAGE, politely, not every event, so a screen
 * reader is not re-read a queue of substeps as they stream.
 */

import { useEffect, useMemo, useRef, useState } from "react";

import {
  formatElapsed,
  isCounting,
  liveStepElapsedMs,
  runHeadline,
  systemNow,
} from "./clock";
import type { RunView, Step } from "./reducer";
import { collapsedSummary, failedStage, formatSeconds } from "./reducer";

const PREFERENCE_KEY = "cockpit-v4:process-panel-open";

function readPreference(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return window.localStorage.getItem(PREFERENCE_KEY) === "open";
  } catch {
    return false;
  }
}

function writePreference(open: boolean): void {
  try {
    window.localStorage.setItem(PREFERENCE_KEY, open ? "open" : "closed");
  } catch {
    /* a browser that refuses storage still gets a working panel */
  }
}

function Marker({ state, failures }: { state: Step["state"]; failures: number }) {
  // A stage that succeeded on a retry is neither a clean tick nor a failure.
  // Saying so is the whole point of an audit trace.
  const recovered = state === "done" && failures > 0;
  const glyph =
    state === "failed"
      ? "✕"
      : recovered
        ? "⟳"
        : state === "done"
          ? "✓"
          : state === "running"
            ? "●"
            : "○";
  const tone =
    state === "failed"
      ? "text-negative"
      : recovered
        ? "text-warning"
        : state === "done"
          ? "text-positive"
          : state === "running"
            ? "text-accent"
            : "text-text-muted";
  return (
    <span aria-hidden className={`w-4 shrink-0 text-center ${tone}`}>
      {glyph}
    </span>
  );
}

function stateWord(state: Step["state"]): string {
  // Every step on screen has started. §33: there is no "not started" row,
  // because a row is drawn when the server says the stage began.
  return state;
}

export function ProcessPanel({
  view,
  operatorView = false,
  onCancel,
  onRetryStatus,
}: {
  view: RunView;
  operatorView?: boolean;
  onCancel?: () => void;
  onRetryStatus?: () => void;
}) {
  const [open, setOpen] = useState<boolean>(false);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const autoExpanded = useRef("");

  useEffect(() => {
    setOpen(readPreference());
  }, []);

  // A failure auto-expands its own step, once, without stealing the user's
  // choice to close the panel again afterwards.
  const failed = failedStage(view);
  useEffect(() => {
    if (failed && autoExpanded.current !== failed) {
      autoExpanded.current = failed;
      setOpen(true);
      setExpanded((prev) => ({ ...prev, [failed]: true }));
    }
  }, [failed]);

  // ONE interval for the whole panel, started only while something is
  // running and cleared the moment it is not. A timer per stage would be a
  // dozen intervals on a busy run and a leak on every one that unmounts
  // mid-flight.
  const [now, setNow] = useState(() => systemNow());
  const counting = isCounting(view);
  useEffect(() => {
    if (!counting) return undefined;
    setNow(systemNow());
    const handle = setInterval(() => setNow(systemNow()), 1000);
    return () => clearInterval(handle);
  }, [counting]);

  // While the run is live this is the moving figure; once it settles
  // `runHeadline` reports the server's authoritative total and stops.
  const summary = counting
    ? runHeadline(view, now)
    : collapsedSummary(view);

  const toggle = () => {
    const next = !open;
    setOpen(next);
    writePreference(next);
  };

  return (
    <section
      data-testid="v4-process-panel"
      data-open={open ? "true" : "false"}
      className="rounded-lg border border-border bg-surface-sunken/60 text-sm"
      aria-label="Process"
    >
      <div className="flex items-center justify-between gap-3 px-3 py-2">
        <p
          data-testid="v4-process-summary"
          className="min-w-0 truncate text-text-secondary"
          aria-live="polite"
        >
          {summary}
        </p>
        <div className="flex shrink-0 items-center gap-2">
          {!view.terminal && onCancel ? (
            <button
              type="button"
              data-testid="v4-stop"
              onClick={onCancel}
              className="rounded border border-border-strong px-2 py-1 text-xs text-text-secondary hover:bg-surface"
            >
              Stop
            </button>
          ) : null}
          <button
            type="button"
            data-testid="v4-toggle-process"
            onClick={toggle}
            aria-expanded={open}
            aria-controls="cockpit-v4-process-detail"
            className="rounded px-2 py-1 text-xs font-medium text-accent hover:bg-surface"
          >
            {open ? "Hide process ▴" : "Show process ▾"}
          </button>
        </div>
      </div>

      {view.connection === "lost" ? (
        <p className="border-t border-warning bg-warning-muted px-3 py-2 text-xs text-warning">
          CONNECTION_LOST — this browser stopped receiving updates. The last
          stage it saw was{" "}
          <strong>{view.steps.find((s) => s.state === "running")?.label ?? "—"}</strong>
          . This says nothing about whether the request itself failed.{" "}
          {onRetryStatus ? (
            <button
              type="button"
              onClick={onRetryStatus}
              className="underline underline-offset-2"
            >
              Check its status
            </button>
          ) : null}
        </p>
      ) : null}

      {open ? (
        <div
          id="cockpit-v4-process-detail"
          className="border-t border-border px-3 py-2"
        >
          <ol className="space-y-1" data-testid="v4-process-steps">
            {view.steps.map((step) => {
              const isOpen = Boolean(expanded[step.instanceId]);
              const hasDetail = step.substeps.length > 0;
              return (
                <li key={step.instanceId}>
                  <div className="flex items-start gap-2">
                    <Marker state={step.state} failures={step.failures} />
                    <div className="min-w-0 flex-1">
                      <button
                        type="button"
                        disabled={!hasDetail}
                        onClick={() =>
                          setExpanded((prev) => ({
                            ...prev,
                            [step.instanceId]: !prev[step.instanceId],
                          }))
                        }
                        aria-expanded={isOpen}
                        className={`flex w-full items-baseline justify-between gap-3 text-left text-text-primary ${
                          hasDetail ? "hover:underline" : "cursor-default"
                        }`}
                      >
                        <span className="truncate">
                          {step.label}
                          <span className="sr-only"> — {stateWord(step.state)}</span>
                        </span>
                        <span
                          data-testid={`v4-step-elapsed-${step.stage}`}
                          data-running={step.state === "running"
                            ? "true" : "false"}
                          className="shrink-0 tabular-nums text-xs text-text-muted"
                        >
                          {step.state === "running"
                            ? formatElapsed(liveStepElapsedMs(step, view, now))
                            : formatSeconds(step.elapsedMs)}
                        </span>
                      </button>
                      {step.detail ? (
                        <p className="truncate text-xs text-text-muted">
                          {step.detail}
                        </p>
                      ) : null}
                      {step.failures > 0 ? (
                        <p
                          data-testid={`v4-step-failures-${step.stage}`}
                          className="text-xs text-warning"
                        >
                          {step.failures === 1
                            ? "1 attempt failed here"
                            : `${step.failures} attempts failed here`}
                          {step.state === "done"
                            ? " before this stage completed"
                            : ""}
                        </p>
                      ) : null}

                      {isOpen ? (
                        <ul className="mt-1 space-y-1 border-l border-border pl-3">
                          {step.substeps.map((sub) => (
                            <li
                              key={sub.seq}
                              data-testid="v4-substep"
                              data-status={sub.status}
                              className="flex items-baseline gap-2 text-xs"
                            >
                              <span className="shrink-0 tabular-nums text-text-muted">
                                {formatSeconds(sub.elapsedMs)}
                              </span>
                              <span
                                className={
                                  sub.status === "failed" || sub.status === "rejected"
                                    ? "text-negative"
                                    : "text-text-secondary"
                                }
                              >
                                {sub.message}
                                {sub.attempt > 1 ? (
                                  <span className="ml-1 text-text-muted">
                                    (attempt {sub.attempt})
                                  </span>
                                ) : null}
                              </span>
                              {operatorView && sub.operation ? (
                                <span className="ml-auto shrink-0 text-text-muted">
                                  {sub.eventType} · {sub.operation}
                                  {sub.detailRef ? ` · ${sub.detailRef}` : ""}
                                </span>
                              ) : null}
                              {sub.errorId ? (
                                <span className="ml-2 font-mono text-negative">
                                  {sub.errorId}
                                </span>
                              ) : null}
                            </li>
                          ))}
                        </ul>
                      ) : null}
                    </div>
                  </div>
                </li>
              );
            })}
          </ol>

          <p className="mt-2 border-t border-border pt-2 text-xs text-text-muted">
            Memory maintenance is separate and never holds this answer open.
          </p>
          {view.errorId ? (
            <p className="mt-1 text-xs text-text-secondary">
              Support reference <span className="font-mono">{view.errorId}</span>
            </p>
          ) : null}
        </div>
      ) : null}
    </section>
  );
}

"use client";

/**
 * The Cockpit thread: a conversation, not a page that answers once.
 *
 * The product problem this exists for
 * -----------------------------------
 * V4 could execute an analytical question and publish an evidence-bound
 * answer, and the experience was still a dashboard. You asked from a landing
 * page, one process panel appeared, one answer appeared, and to ask the
 * obvious next question you scrolled back up to the box you started in. There
 * was no transcript, so the second question felt like starting over, and the
 * answer read as the end of the interaction when the follow-up is the point.
 *
 * So: a thread. The question sits at the top, the process runs underneath it,
 * the answer appends below that, and the composer is waiting where your eye
 * already is. Ask again and the exchange appends -- it does not replace what
 * came before. Five questions render as five exchanges.
 *
 * What did NOT come back with the shape
 * --------------------------------------
 * None of the previous Cockpit's backend. No `/investigations`, no
 * `/agentic/officer`, no old Ask flow, no shim translating either. The run
 * lifecycle, the evidence model, the release binding and the numeric
 * rendering are V4's, unchanged by this file. This is the interaction the old
 * product got right, over the architecture the new one got right.
 *
 * Reloading is free
 * -----------------
 * The transcript is the server's. A refresh reads it back and re-follows only
 * a run that is genuinely still working -- it never re-asks, because asking
 * again spends the analysis twice and tells the reader nothing about the
 * first one.
 */

import * as React from "react";

import { InvestigationBar } from "@/components/guided/investigation-bar";

import { comparisonPeriod, periodLabel, reportingPeriod } from "./period";

import {
  acknowledge,
  cancelRun,
  forgetRun,
  readStatus,
  readTrace,
  recallRun,
  rememberRun,
  readThread,
  renameThread,
  saveAnalysis,
  shareItem,
  createInvestigation,
  deliveryWording,
  type Notification,
  startRun,
  watch,
  type FinalResponse,
  type RunMode,
  type ThreadTranscript,
  type ThreadTurn,
} from "./client";
import { chipsToShow } from "./follow-ups";
import { AnswerActions } from "./answer-actions";
import { ProcessPanel } from "./process-panel";
import { TERMINAL_RUN_STATES, initial, reduce, type RunView }
  from "./reducer";
import { ResponsePanel } from "./response-panel";
import { Visuals } from "./visuals";
import { RecipientPicker } from "./recipient-picker";

/** One exchange already on the server. */
type Settled = {
  key: string;
  runId: string;
  question: string;
  answer: FinalResponse;
};

function settled(turn: ThreadTurn): Settled {
  return {
    key: turn.turn_id,
    runId: turn.run_id,
    question: turn.question,
    answer: turn.answer as FinalResponse,
  };
}

// ---- the pieces ---------------------------------------------------------

function UserTurn({ question }: { question: string }) {
  return (
    <div data-testid="v4-turn-user" className="flex justify-end">
      <p
        dir="auto"
        className="max-w-[48rem] rounded-2xl rounded-br-sm bg-accent px-4 py-2.5 text-sm text-accent-contrast"
      >
        {question}
      </p>
    </div>
  );
}

/**
 * The trace of a turn that has already finished. §28.
 *
 * The live panel shows a run while it happens. A reader coming back to a
 * past turn -- their own, an hour later, or after a reload -- had no way to
 * see the same thing, and "trust the answer" is not the claim being made.
 *
 * Loaded on demand, because a transcript of twenty turns should not fetch
 * twenty event streams to render. Nothing here costs a model call.
 */
function TurnTrace({ runId }: { runId: string }) {
  const [view, setView] = React.useState<RunView | null>(null);
  const [busy, setBusy] = React.useState(false);
  const [failed, setFailed] = React.useState("");

  const open = React.useCallback(async () => {
    if (view || busy) {
      setView(null);
      return;
    }
    setBusy(true);
    setFailed("");
    try {
      const trace = await readTrace(runId);
      let next = reduce(initial(runId), { type: "start", runId });
      for (const event of trace.events) {
        next = reduce(next, { type: "event", event });
      }
      // Settled from the RECORD, not from whichever event happened to be
      // last: a stream that dropped its final frame must not leave a
      // finished run looking as though it is still working.
      next = {
        ...next,
        terminal: true,
        state: trace.state,
        errorCode: trace.error_code,
        elapsedIsAuthoritative: true,
        steps: next.steps.map((step) =>
          step.state === "running" ? { ...step, state: "done" as const } : step,
        ),
      };
      setView(next);
    } catch (cause) {
      setFailed(
        cause instanceof Error ? cause.message : "The trace could not be read.",
      );
    } finally {
      setBusy(false);
    }
  }, [busy, runId, view]);

  return (
    <div data-testid="v4-turn-trace">
      <div className="flex flex-wrap items-center gap-3">
        <button
          type="button"
          data-testid="v4-view-trace"
          onClick={() => void open()}
          aria-expanded={Boolean(view)}
          className="text-xs font-medium text-accent hover:underline"
        >
          {busy ? "Reading trace…" : view ? "Hide trace" : "View trace"}
        </button>
        {/* WHAT THE STAGE LIST DOES NOT SAY. The trace above shows that
            the analysis ran; this shows what was understood, what query
            was written, what was refused and where each figure came
            from. Two different questions, so two different controls. */}
        <a
          data-testid="v4-view-governance"
          href={`/cockpit/trace/${encodeURIComponent(runId)}`}
          className="text-xs font-medium text-accent hover:underline"
        >
          How this was worked out
        </a>
      </div>
      {failed ? (
        <p className="mt-1 text-xs text-negative">{failed}</p>
      ) : null}
      {view ? (
        <div className="mt-2">
          <ProcessPanel view={view} />
        </div>
      ) : null}
    </div>
  );
}

function AssistantTurn({
  turn,
  onAsk,
}: {
  turn: Settled;
  onAsk: (question: string) => void;
}) {
  // The answer body is the SAME component the live run renders, driven by a
  // view reconstructed from the stored turn. A second renderer for answers
  // read back from the server would be a second set of rules about
  // dispositions, evidence links and suggested questions, and the two would
  // drift the first time either changed.
  const view = React.useMemo(
    () => ({
      ...initial(turn.runId),
      terminal: true,
      state: "COMPLETED",
      response: turn.answer,
    }),
    [turn.runId, turn.answer],
  );

  return (
    <div data-testid="v4-turn-assistant" className="space-y-4">
      <ResponsePanel
        view={view}
        question={turn.question}
        onAsk={onAsk}
        showSuggestions={false}
      />
      <Visuals tables={turn.answer.tables ?? []}
               charts={turn.answer.charts ?? []} runId={turn.runId} />
      <TurnTrace runId={turn.runId} />
    </div>
  );
}


/** What a seeded investigation already knows, before anything is asked. */
function SeedCard({
  context,
  threadId,
}: {
  context: ThreadTranscript["context"];
  threadId: string;
}) {
  const body = (context?.body ?? {}) as Record<string, unknown>;
  if (context?.kind !== "attention_item") return null;
  const rows: [string, string][] = [
    ["Segment", String(body.segment ?? "")],
    // A seed carries whichever calendar its book keeps, so read the
    // neutral field and fall back to whichever legacy key is filled.
    ["Period", [periodLabel(reportingPeriod(body as never)),
                periodLabel(comparisonPeriod(body as never))]
      .filter(Boolean).join(" vs ")],
    ["Measure", String(body.metric_label ?? body.metric ?? "")],
  ].filter(([, value]) => Boolean(value)) as [string, string][];

  return (
    <section
      // The same name the concept has always had. One testid for one thing:
      // this card IS the investigation context, wherever it is rendered.
      data-testid="investigation-context"
      data-thread-id={threadId}
      data-segment={String(body.segment ?? "")}
      className="rounded-lg border border-accent bg-accent-muted/60 px-4 py-3"
    >
      <p className="text-xs font-medium uppercase tracking-wide text-accent">
        Investigating
      </p>
      <p dir="auto" className="mt-1 text-sm font-medium text-text-primary">
        {String(body.headline ?? "")}
      </p>
      <dl className="mt-2 flex flex-wrap gap-x-6 gap-y-1 text-xs text-text-secondary">
        {rows.map(([label, value]) => (
          <div key={label} className="flex gap-1.5">
            <dt className="text-text-muted">{label}</dt>
            <dd className="font-medium text-text-primary" dir="auto">{value}</dd>
          </div>
        ))}
      </dl>
      {body.issue ? (
        <p dir="auto" className="mt-2 max-w-[68ch] text-xs text-text-secondary">
          {String(body.issue)}
        </p>
      ) : null}
    </section>
  );
}

/**
 * What to ask next, where the next question gets typed.
 *
 * §24: the chips belong between the answer and the composer, not buried in
 * the answer panel above a chart and a table. A suggestion the reader has to
 * scroll back up to find is a suggestion that does not get used.
 *
 * These come from the LATEST answer. An older turn's follow-ups are answered
 * by the turns after it and offering them again is offering to go backwards.
 */
function FollowUps({
  questions,
  busy,
  onAsk,
}: {
  questions: string[];
  busy: boolean;
  onAsk: (question: string) => void;
}) {
  if (!questions.length) return null;
  // §34. An OPAQUE band, with the label on its own line.
  //
  // The strip used to sit in the transparent top of the composer's gradient
  // with `items-center`, so a chip that wrapped to two lines overlapped the
  // transcript showing through behind it, and the "Ask next" label collided
  // with the first chip at narrow widths. Three fixes, all of them the same
  // fix: give the strip its own background so nothing shows through it,
  // break the label onto its own row so it can never share a line with a
  // chip, and align the chips to the TOP of the row so a chip that wraps
  // grows downward into the band's own padding rather than over its
  // neighbour.
  return (
    <div
      data-testid="v4-followups"
      className="mb-3 rounded-xl border border-border bg-surface/95 px-3 py-2.5 shadow-[0_-4px_12px_-8px_rgba(15,23,42,0.25)] backdrop-blur-sm"
    >
      <span className="mb-1.5 block text-[11px] uppercase tracking-wide text-text-muted">
        Ask next
      </span>
      <div className="flex flex-wrap items-start gap-x-2 gap-y-2">
        {questions.map((question) => (
          <button
            key={question}
            type="button"
            data-testid="v4-followup-chip"
            disabled={busy}
            dir="auto"
            onClick={() => onAsk(question)}
            className="max-w-full rounded-full border border-border-strong bg-surface px-3 py-1.5 text-left text-xs leading-5 text-text-secondary hover:border-border-strong hover:bg-surface-sunken disabled:cursor-not-allowed disabled:opacity-50"
          >
            {question}
          </button>
        ))}
      </div>
    </div>
  );
}

function Composer({
  onAsk,
  busy,
  mode,
  onMode,
  followUps,
}: {
  onAsk: (question: string) => void;
  busy: boolean;
  mode: RunMode;
  onMode: (mode: RunMode) => void;
  followUps: string[];
}) {
  const [text, setText] = React.useState("");
  const submit = () => {
    const question = text.trim();
    if (!question || busy) return;
    setText("");
    onAsk(question);
  };

  return (
    <div
      data-testid="v4-composer"
      className="sticky bottom-0 z-10 -mx-1 bg-gradient-to-t from-surface via-surface to-transparent px-1 pb-4 pt-6"
    >
      {/*
        Inside the sticky block, so the suggestions travel with the box they
        feed. A strip in normal flow above a sticky composer is a strip that
        scrolls away from it -- which is the same problem as burying it in
        the answer, arrived at differently.
      */}
      <FollowUps questions={followUps} busy={busy} onAsk={onAsk} />
      <div className="rounded-xl border border-border-strong bg-surface shadow-sm focus-within:border-border-strong">
        <textarea
          data-testid="v4-composer-input"
          dir="auto"
          rows={2}
          value={text}
          disabled={busy}
          placeholder="Ask a follow-up…"
          onChange={(event) => setText(event.target.value)}
          onKeyDown={(event) => {
            // Enter asks; Shift+Enter is a new line. The same contract every
            // chat surface has trained every reader to expect.
            if (event.key === "Enter" && !event.shiftKey) {
              event.preventDefault();
              submit();
            }
          }}
          className="w-full resize-none rounded-xl px-4 py-3 text-sm text-text-primary outline-none disabled:bg-surface-sunken"
        />
        <div className="flex items-center justify-between gap-3 border-t border-border px-3 py-2">
          <label className="flex items-center gap-2 text-xs text-text-muted">
            <span>Depth</span>
            <select
              data-testid="v4-composer-mode"
              value={mode}
              onChange={(event) => onMode(event.target.value as RunMode)}
              className="rounded border border-border px-2 py-1 text-xs"
            >
              <option value="standard">Standard</option>
              <option value="deep">Deep</option>
            </select>
          </label>
          <button
            type="button"
            data-testid="v4-composer-send"
            onClick={submit}
            disabled={busy || !text.trim()}
            className="rounded-lg bg-accent px-4 py-1.5 text-sm font-medium text-accent-contrast disabled:bg-border-strong"
          >
            {busy ? "Working…" : "Ask"}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * What you can do with the conversation, not with one answer in it.
 *
 * These act on the LATEST answered turn, because that is what a colleague
 * opening a shared link needs to land on and what an investigation entry
 * should point at. The per-answer actions further down the transcript still
 * act on their own turn; this is the shortcut for the one you just read.
 *
 * "Add to Project" is deliberately absent. Projects are a main-CreditProbe
 * surface and this isolated V4 runtime does not serve them, so there is no
 * endpoint behind a button here. A button that looks like it works and does
 * not is worse than the sentence saying so. Investigations ARE V4-native and
 * are offered here instead.
 */
function ThreadActions({
  runId,
  threadId,
  title,
}: {
  runId: string;
  threadId: string;
  title: string;
}) {
  const [panel, setPanel] = React.useState<"" | "share" | "investigate">("");
  const [audience, setAudience] = React.useState("");
  const [recipient, setRecipient] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [busy, setBusy] = React.useState(false);
  const [status, setStatus] = React.useState("");
  const [notification, setNotification] =
    React.useState<Notification | null>(null);
  const [notified, setNotified] = React.useState(false);

  const run = React.useCallback(async (work: () => Promise<string>) => {
    setBusy(true);
    setStatus("");
    try {
      setStatus(await work());
    } catch (cause) {
      setStatus(
        cause instanceof Error
          ? `That did not go through: ${cause.message}`
          : "That did not go through.",
      );
    } finally {
      setBusy(false);
    }
  }, []);

  if (!runId) return null;
  const label = title || "Cockpit conversation";

  return (
    <div data-testid="v4-thread-actions" className="mt-3">
      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          data-testid="v4-thread-share"
          aria-pressed={panel === "share"}
          onClick={() => setPanel(panel === "share" ? "" : "share")}
          className="rounded border border-border-strong px-3 py-1.5 text-xs text-text-secondary hover:bg-surface-sunken"
        >
          Share
        </button>
        <button
          type="button"
          data-testid="v4-thread-investigate"
          aria-pressed={panel === "investigate"}
          onClick={() => setPanel(panel === "investigate" ? "" : "investigate")}
          className="rounded border border-border-strong px-3 py-1.5 text-xs text-text-secondary hover:bg-surface-sunken"
        >
          Add to investigation
        </button>
        <a
          data-testid="v4-thread-trace"
          // `/cockpit/trace`, not `/trace`. The latter is the legacy
          // reasoning map, which does `Number(runId)` on a `run-<hex>` id
          // and gets NaN -- so this button had been dead since V4 shipped.
          href={`/cockpit/trace/${encodeURIComponent(runId)}`}
          className="rounded border border-border-strong px-3 py-1.5 text-xs text-text-secondary hover:bg-surface-sunken"
        >
          Trace
        </a>
      </div>

      {panel === "share" ? (
        <div className="mt-2 max-w-md space-y-2" data-testid="v4-thread-share-panel">
          <p className="text-xs text-text-muted">
            Shares the latest answer in this conversation.
          </p>
          <label className="block text-xs text-text-secondary">
            Audience (who this is shared with)
            <input
              data-testid="v4-thread-share-audience"
              value={audience}
              onChange={(event) => setAudience(event.target.value)}
              className="mt-1 w-full rounded border border-border-strong px-2 py-1 text-sm"
            />
          </label>
          {/* THE PART THAT ACTUALLY REACHES SOMEBODY. The audience above
              records who the share is for; this sends them the message. */}
          <RecipientPicker value={recipient} onChange={setRecipient} />
          <label className="block text-xs text-text-secondary">
            Notify by email (optional)
            <input
              data-testid="v4-thread-share-email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              className="mt-1 w-full rounded border border-border-strong px-2 py-1 text-sm"
            />
          </label>
          <button
            type="button"
            data-testid="v4-thread-share-submit"
            disabled={busy || !audience.trim()}
            onClick={() =>
              void run(async () => {
                const saved = await saveAnalysis({
                  run_id: runId, title: label.slice(0, 120),
                });
                const result = await shareItem({
                  subject_kind: "saved_analysis",
                  subject_id: saved.saved_id,
                  audience_id: audience.trim(),
                  notify_in_app: recipient.trim(),
                  notify_email: email.trim(),
                });
                setNotification(result.notification);
                setNotified(true);
                return `Shared with ${result.share.audience_id}.`;
              })
            }
            className="rounded bg-accent px-3 py-1 text-xs font-medium text-accent-contrast disabled:opacity-50"
          >
            Share
          </button>
          {notified ? (
            <p
              data-testid="v4-thread-share-delivery"
              className={
                "text-xs " +
                (notification?.delivered ? "text-positive" : "text-warning")
              }
            >
              {deliveryWording(notification)}
            </p>
          ) : null}
        </div>
      ) : null}

      {panel === "investigate" ? (
        <div
          className="mt-2 max-w-md space-y-2"
          data-testid="v4-thread-investigate-panel"
        >
          <p className="text-xs text-text-muted">
            Opens an investigation for this conversation.
          </p>
          <button
            type="button"
            data-testid="v4-thread-investigate-submit"
            disabled={busy}
            onClick={() =>
              void run(async () => {
                const record = await createInvestigation({
                  title: label.slice(0, 120),
                  origin: "cockpit_thread",
                  thread_id: threadId,
                });
                return `Investigation opened: ${record.title}.`;
              })
            }
            className="rounded bg-accent px-3 py-1 text-xs font-medium text-accent-contrast disabled:opacity-50"
          >
            Open investigation
          </button>
          <p className="text-xs text-text-muted" data-testid="v4-thread-no-projects">
            Add to Project is not available in this isolated Cockpit V4
            runtime. Projects are served by the main CreditProbe backend,
            which this instance does not start, so nothing here would reach
            one. Investigations are the V4-native equivalent.
          </p>
        </div>
      ) : null}

      {status ? (
        <p className="mt-2 text-xs text-text-secondary" data-testid="v4-thread-action-status">
          {status}
        </p>
      ) : null}
    </div>
  );
}

function ThreadHeader({
  title,
  named,
  turnCount,
  latestRunId,
  threadId,
  domainId,
  domainLabel,
  onRename,
  onHome,
}: {
  title: string;
  /**
   * Whether the server has said what this conversation is called yet.
   *
   * Separate from `title` being empty, because those are different facts
   * and were being rendered as the same one. See the header below.
   */
  named: boolean;
  turnCount: number;
  latestRunId: string;
  threadId: string;
  domainId: string;
  domainLabel: string;
  onRename: (title: string) => void;
  onHome: () => void;
}) {
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(title);
  React.useEffect(() => setDraft(title), [title]);

  return (
    <header
      data-testid="v4-thread-header"
      className="border-b border-border pb-4"
    >
      {/*
        §22: the way back is at the TOP LEFT, above the title, where every
        reader of every application already looks for it. It used to be a
        small button on the far right of the header row, level with Rename,
        which is where a reader looks for actions ON this conversation and
        not for the exit from it.
      */}
      <button
        type="button"
        data-testid="v4-back-to-cockpit"
        onClick={onHome}
        className="-ml-1 mb-2 inline-flex items-center gap-1.5 rounded px-1 py-0.5 text-sm text-text-muted hover:bg-surface-sunken hover:text-text-primary"
      >
        <span aria-hidden="true">←</span> Cockpit
      </button>

      <div className="flex flex-wrap items-start justify-between gap-3">
      <div className="min-w-0">
        {editing ? (
          <form
            className="flex items-center gap-2"
            onSubmit={(event) => {
              event.preventDefault();
              const next = draft.trim();
              if (next) onRename(next);
              setEditing(false);
            }}
          >
            <input
              data-testid="v4-thread-title-input"
              autoFocus
              dir="auto"
              value={draft}
              onChange={(event) => setDraft(event.target.value)}
              className="w-[28rem] max-w-full rounded border border-border-strong px-2 py-1 text-lg"
            />
            <button
              type="submit"
              data-testid="v4-thread-rename-save"
              className="rounded bg-accent px-3 py-1 text-xs text-accent-contrast"
            >
              Save
            </button>
          </form>
        ) : named ? (
          <h1
            data-testid="v4-thread-title"
            dir="auto"
            className="truncate text-xl font-semibold text-text-primary"
          >
            {title || "New conversation"}
          </h1>
        ) : (
          /*
            "New conversation" means this conversation has no name. It was
            also what a reader saw for the moment between a refresh and the
            transcript arriving, because `transcript?.title ?? ""` collapses
            "not loaded yet" and "loaded, unnamed" into the same empty
            string. So a thread the reader had named appeared, briefly, to
            have been renamed back on every reload.

            A heading is a claim about what something is called. While the
            server has not said, the honest heading is that we are still
            asking -- and it carries a DIFFERENT test id, so a test reading
            the title waits for a title rather than racing the fetch and
            quoting the placeholder.
          */
          <h1
            data-testid="v4-thread-title-loading"
            className="truncate text-xl font-semibold text-text-muted"
          >
            Opening this conversation…
          </h1>
        )}
        <p className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted">
          {/*
            §35: which book this conversation is held in, stated rather than
            inferred. A reader with a corporate and a retail thread open
            should not have to read the answers to tell them apart.
          */}
          {domainLabel ? (
            <span
              data-testid="v4-thread-domain"
              data-domain={domainId}
              className="rounded-full border border-border-strong px-2 py-0.5 text-[11px] font-medium text-text-secondary"
            >
              {domainLabel}
            </span>
          ) : null}
          <span data-testid="v4-thread-turns">
            {turnCount} message{turnCount === 1 ? "" : "s"}
          </span>
        </p>
        <ThreadActions
          runId={latestRunId}
          threadId={threadId}
          title={title}
        />
      </div>
      <div className="flex shrink-0 items-center gap-2">
        {/* Offered once there is a name to change. Before the transcript
            lands the draft would open empty, and saving it would replace a
            name the reader had not seen with nothing. */}
        <button
          type="button"
          data-testid="v4-thread-rename"
          disabled={!named}
          onClick={() => setEditing((prev) => !prev)}
          className="rounded border border-border-strong px-3 py-1.5 text-xs text-text-secondary hover:bg-surface-sunken disabled:opacity-50"
        >
          Rename
        </button>
      </div>
      </div>
    </header>
  );
}

// ---- the thread ---------------------------------------------------------

export function CockpitV4Thread({
  threadId,
  onHome,
}: {
  threadId: string;
  onHome: () => void;
}) {
  const [transcript, setTranscript] = React.useState<ThreadTranscript | null>(
    null,
  );
  const [loadError, setLoadError] = React.useState("");
  const [live, setLive] = React.useState<
    { question: string; runId: string } | null
  >(null);
  const [view, dispatch] = React.useReducer(reduce, initial());
  const [mode, setMode] = React.useState<RunMode>("standard");
  const [error, setError] = React.useState("");
  const resumed = React.useRef(false);
  const bottom = React.useRef<HTMLDivElement | null>(null);

  const load = React.useCallback(async () => {
    try {
      setTranscript(await readThread(threadId));
    } catch (cause) {
      setLoadError(
        cause instanceof Error ? cause.message : "This conversation could not be opened.",
      );
    }
  }, [threadId]);

  React.useEffect(() => {
    void load();
  }, [load]);

  /**
   * Follow a run that is already going: attach the stream, settle, reload.
   *
   * Shared by asking and by RESUMING after a refresh, because the two are the
   * same thing from the moment the run id exists -- and a resumed run that
   * followed a different code path would be a second set of rules about
   * cursors, settlement and acknowledgement.
   */
  const follow = React.useCallback(
    (runId: string) =>
      watch(runId, {
        onEvent: (event) => dispatch({ type: "event", event }),
        onConnectionState: (state) =>
          dispatch({ type: "connection", state }),
        onSettled: async () => {
          try {
            const status = await readStatus(runId);
            dispatch({ type: "settled", status });
            await acknowledge(runId).catch(() => undefined);
          } catch {
            /* the transcript reload below is the authority anyway */
          }
          forgetRun();
          await load();
        },
      }),
    [load],
  );

  const ask = React.useCallback(
    async (question: string) => {
      if (!question.trim()) return;
      setError("");
      // The previous run's panel gives way to this one. Its exchange is
      // already in the transcript by now, so the conversation keeps it.
      await load();
      setLive({ question, runId: "" });
      dispatch({ type: "start", runId: "" });
      try {
        const started = await startRun({ question, mode, threadId });
        setLive({ question, runId: started.run_id });
        dispatch({ type: "start", runId: started.run_id });
        // The pointer a refresh picks the run back up from. The transcript
        // itself is the server's; this is only "which run is still working".
        rememberRun({
          runId: started.run_id, threadId, cursor: 0, question,
        });
        // The live turn STAYS once the answer arrives. Its process panel is
        // where the stages, their timings and any failed attempt live, and
        // clearing it the moment the answer landed took the trace off the
        // screen at exactly the point a reader wants to check it (§56). The
        // turn it belongs to is filtered out of the reloaded transcript, so
        // the exchange is drawn once.
        return follow(started.run_id);
      } catch (cause) {
        setLive(null);
        setError(
          cause instanceof Error ? cause.message : "The request was not accepted.",
        );
      }
      return undefined;
    },
    [load, mode, threadId],
  );

  /**
   * Pick a run back up after a refresh.
   *
   * A run outlives this page. Reloading while one is working must reconnect
   * to THAT run rather than ask again -- asking again spends the analysis
   * twice and tells the reader nothing about the first one. The status is
   * read first, so a run that settled while the browser was away is settled
   * here rather than followed into a stream that has already ended.
   */
  React.useEffect(() => {
    if (resumed.current) return;
    resumed.current = true;
    const active = recallRun();
    if (!active || active.threadId !== threadId) return;
    let stop: (() => void) | undefined;
    void (async () => {
      try {
        const status = await readStatus(active.runId);
        if (TERMINAL_RUN_STATES.has(status.state)) {
          forgetRun();
          return;
        }
        // The reader's own words, from the pointer that was written when
        // the run started. A turn that renders blank above a visibly
        // working panel reads as a bug in the conversation.
        setLive({ question: active.question ?? "", runId: active.runId });
        dispatch({ type: "start", runId: active.runId });
        stop = follow(active.runId);
      } catch {
        forgetRun();
      }
    })();
    return () => stop?.();
  }, [follow, threadId]);

  React.useEffect(() => {
    bottom.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [transcript?.turn_count, live?.question, view.terminal]);

  const rename = React.useCallback(
    async (title: string) => {
      try {
        const renamed = await renameThread(threadId, title);
        setTranscript((prev) =>
          prev ? { ...prev, title: renamed.title } : prev,
        );
      } catch {
        /* a rename that did not take is not shown as if it had */
      }
    },
    [threadId],
  );

  // The exchange that is still on screen as a live run is not drawn a second
  // time from the transcript. Both are the same question and the same answer;
  // the live one additionally carries its process panel.
  const turns = (transcript?.turns ?? [])
    .filter((turn) => !live || turn.run_id !== live.runId)
    .map(settled);
  // "Busy" is about whether a NEW question can be asked, which a finished run
  // does not prevent -- the panel simply stays on screen.
  const busy = Boolean(live) && !view.terminal;

  // The follow-ups belong to the NEWEST answer: the live one once it has
  // settled, otherwise the last stored turn. While a run is working there
  // are none, because the suggestions that were on screen belong to a
  // question already being followed up.
  const latest = live && view.terminal
    ? view.response
    : turns.length
      ? turns[turns.length - 1].answer
      : null;
  // §31/§32. See `chipsToShow`: the answer's own suggestions, else the
  // book's deterministic fallbacks, else -- while the thread is still empty
  // -- the questions it was opened on.
  const followUps = chipsToShow({
    busy,
    answered: Boolean(latest),
    domainId: transcript?.domain_id ?? "",
    offered: latest?.suggested_questions,
    opening: transcript?.opening_questions,
  });

  if (loadError) {
    return (
      <div data-testid="v4-thread-error" className="mx-auto max-w-2xl py-16">
        <p className="text-sm text-negative">{loadError}</p>
        <button
          type="button"
          onClick={onHome}
          className="mt-3 text-sm text-accent hover:underline"
        >
          Back to Cockpit home
        </button>
      </div>
    );
  }

  return (
    <div
      data-testid="cockpit-v4-thread"
      data-thread-id={threadId}
      className="mx-auto flex w-full max-w-[90rem] flex-col px-4 py-8 sm:px-6 lg:px-10"
    >
      <ThreadHeader
        title={transcript?.title ?? ""}
        named={transcript !== null}
        turnCount={turns.length + (live ? 1 : 0)}
        domainId={transcript?.domain_id ?? ""}
        domainLabel={transcript?.domain_short_label ?? ""}
        latestRunId={
          // The newest ANSWERED run: the live one once it has settled,
          // otherwise the last turn already in the transcript. A run still
          // working has nothing to share yet.
          live && view.terminal && view.runId
            ? view.runId
            : turns.length
              ? turns[turns.length - 1].runId
              : ""
        }
        threadId={threadId}
        onRename={(title) => void rename(title)}
        onHome={onHome}
      />

      <div className="mt-6 space-y-10">
        <SeedCard context={transcript?.context ?? {}}
                  threadId={threadId} />
        {/* Guided Workspace P3: investigation path + next-best questions,
            submitted through this thread's own `ask`. Renders nothing
            unless NEXT_PUBLIC_GUIDED_WORKSPACE=1 and the thread began
            from a guided issue. */}
        <React.Suspense fallback={null}>
          <InvestigationBar threadId={threadId} busy={busy}
                            turnCount={turns.length}
                            onAsk={(q) => void ask(q)} />
        </React.Suspense>

        {turns.map((turn) => (
          <article key={turn.key} className="space-y-4">
            <UserTurn question={turn.question} />
            <AssistantTurn turn={turn} onAsk={(q) => void ask(q)} />
          </article>
        ))}

        {live ? (
          <article className="space-y-4" data-testid="v4-turn-live">
            <UserTurn question={live.question} />
            <ProcessPanel
              view={view}
              onCancel={
                view.runId && !view.terminal
                  ? () => void cancelRun(view.runId).catch(() => undefined)
                  : undefined
              }
              onRetryStatus={
                view.runId
                  ? () =>
                      void readStatus(view.runId)
                        .then((status) =>
                          dispatch({ type: "settled", status }),
                        )
                        .catch(() => undefined)
                  : undefined
              }
            />
            {/*
              The answer lands HERE, under the process panel that produced
              it, and a run that stopped shows the stop in the same place.
              §55: one failed exchange does not wipe the conversation it
              happened in -- the turns before it are untouched, and the
              composer below is still available.
            */}
            {view.terminal ? (
              // The same turn marker a settled exchange carries. This IS
              // the assistant's turn -- it simply still has the process
              // panel that produced it attached above.
              <div data-testid="v4-turn-assistant" className="space-y-4">
                <ResponsePanel
                  view={view}
                  question={live.question}
                  threadId={threadId}
                  onAsk={(q) => void ask(q)}
                  showSuggestions={false}
                />
                {view.response ? (
                  <Visuals
                    tables={view.response.tables ?? []}
                    charts={view.response.charts ?? []}
                    runId={view.runId}
                  />
                ) : null}
              </div>
            ) : null}
          </article>
        ) : null}

        {error ? (
          <p data-testid="v4-thread-ask-error" className="text-sm text-negative">
            {error}
          </p>
        ) : null}
      </div>

      <div ref={bottom} />
      <Composer
        onAsk={(question) => void ask(question)}
        busy={busy}
        mode={mode}
        onMode={setMode}
        followUps={followUps}
      />
    </div>
  );
}

"use client";

/**
 * Charts and tables, drawn from what the server already validated.
 *
 * Nothing in this file computes anything. Every figure arrives twice from the
 * backend -- `canonical`, which is the full-precision value the arithmetic and
 * the ordering ran on, and `display`, which is that same value written by the
 * one display policy that decides money shows no decimals and a share shows
 * two. This component picks the second and lays it out.
 *
 * That division is the whole point. A frontend that rounded for itself would
 * be a second opinion about a number the server had already published, and
 * the first time the two disagreed nobody would be able to say which was the
 * answer.
 *
 * Bars are scaled from the CANONICAL values, never the displayed strings:
 * "SAR 9,000 million" sorts above "SAR 40,599 million" as text, and a bar
 * chart drawn from formatted labels is a bar chart of string lengths.
 *
 * Drawn as plain SVG and a plain table. A charting library would bring its own
 * number formatting, its own locale rules and its own idea of a sensible axis,
 * and every one of those is a place for the published figure to change on its
 * way to the screen.
 */

import * as React from "react";

import {
  AxisCaption,
  Legend,
  Plot,
  Ruler,
  slotColor,
  useWindow,
} from "./chart-frame";
import { PLOT_BOX, bandOf, extentOf, slice, xOf, yOf } from "./chart-frame";
import { px } from "./chart-geometry";
import type { HoverPoint } from "./chart-frame";
import type { ChartPoint, RenderedChart, RenderedTable } from "./client";
import { ErrorBoundary } from "@/components/system/error-boundary";
import { ChartDownload, TableDownload } from "./figure-download";
import { TOP_N, choose, numeric, text } from "./visual-choice";
import type { ChartKind } from "./visual-choice";

/**
 * The scale this chart is drawn against.
 *
 * THE SERVER'S, whenever it published one. The data is the fallback, for
 * a thread saved before axes existed -- a reader's own history must not
 * stop drawing because the contract grew a field.
 */
function scaleOf(chart: RenderedChart, values: number[], zeroBased: boolean) {
  const [low, high] = extentOf(chart.y_axis, values, { zeroBased });
  return { low, high, span: high - low || 1 };
}

/** Every named measure of one point, for the hover layer. */
function hoverOf(point: ChartPoint | undefined, columns: string[]): HoverPoint | null {
  if (!point) return null;
  return {
    label: text(point.label),
    rowId: point.row_id,
    values: columns.map((column, slot) => ({
      name: column,
      // The server's string, always. Never derived from `values`.
      display: text(point.display?.[column]),
      slot,
    })),
  };
}

export { TOP_N, chartIsUseful } from "./visual-choice";

// ---- table --------------------------------------------------------------

export function ResultTable({ table, runId }: {
  table: RenderedTable;
  /** Absent in a preview, where there is no stored run to export from. */
  runId?: string;
}) {
  const rows = table.rows ?? [];
  const [showAll, setShowAll] = React.useState(false);
  const [sort, setSort] = React.useState<{ column: string; desc: boolean }
    | null>(null);

  const ordered = React.useMemo(() => {
    if (!sort) return rows;
    // Sorted on CANONICAL values. Sorting the displayed strings would order
    // a money column alphabetically.
    const copy = [...rows];
    copy.sort((a, b) => {
      const left = numeric(a.canonical[sort.column]);
      const right = numeric(b.canonical[sort.column]);
      if (left !== null && right !== null) return left - right;
      return text(a.canonical[sort.column]).localeCompare(
        text(b.canonical[sort.column]),
      );
    });
    return sort.desc ? copy.reverse() : copy;
  }, [rows, sort]);

  const shown = showAll ? ordered : ordered.slice(0, TOP_N);
  const hidden = ordered.length - shown.length;

  if (!rows.length) {
    return (
      <p data-testid="v4-table-empty" className="text-sm text-text-secondary">
        {table.title ? `${table.title}: ` : ""}no rows matched.
      </p>
    );
  }

  return (
    <figure data-testid="v4-result-table" className="min-w-0">
      {table.title ? (
        <figcaption className="mb-2 flex items-center gap-2 text-sm font-medium text-text-primary">
          <span className="min-w-0 truncate">
            {table.title}
            <span className="ml-2 font-normal text-text-muted">
              {table.row_count ?? rows.length} row
              {(table.row_count ?? rows.length) === 1 ? "" : "s"}
            </span>
          </span>
          {runId && table.artifact_id ? (
            <span className="ml-auto shrink-0">
              <TableDownload runId={runId} artifactId={table.artifact_id} />
            </span>
          ) : null}
        </figcaption>
      ) : null}
      <div className="overflow-x-auto rounded border border-border">
        <table className="w-full border-collapse text-sm">
          <thead className="bg-surface-sunken text-left">
            <tr>
              {table.columns.map((column) => (
                <th key={column} scope="col" className="px-3 py-2 font-medium">
                  <button
                    type="button"
                    data-testid={`v4-table-sort-${column}`}
                    className="text-text-secondary hover:underline"
                    onClick={() =>
                      setSort((prev) =>
                        prev && prev.column === column
                          ? { column, desc: !prev.desc }
                          : { column, desc: true },
                      )
                    }
                  >
                    {column}
                    {sort?.column === column ? (sort.desc ? " ▾" : " ▴") : ""}
                  </button>
                  {table.column_units?.[column] ? (
                    <span className="ml-1 font-normal text-xs text-text-muted">
                      {table.column_units[column]}
                    </span>
                  ) : null}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {shown.map((row) => (
              <tr
                key={row.row_id}
                data-testid="v4-table-row"
                className="border-t border-border"
              >
                {table.columns.map((column) => (
                  <td
                    key={column}
                    className="px-3 py-2 tabular-nums text-text-primary"
                    dir="auto"
                  >
                    {text(row.display[column])}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {hidden > 0 ? (
        <button
          type="button"
          data-testid="v4-table-show-all"
          onClick={() => setShowAll(true)}
          className="mt-2 text-xs font-medium text-accent hover:underline"
        >
          View all {ordered.length} rows ({hidden} more)
        </button>
      ) : null}
      {showAll && ordered.length > TOP_N ? (
        <button
          type="button"
          data-testid="v4-table-show-top"
          onClick={() => setShowAll(false)}
          className="mt-2 text-xs font-medium text-accent hover:underline"
        >
          Show top {TOP_N}
        </button>
      ) : null}
    </figure>
  );
}

// ---- chart --------------------------------------------------------------

/** The series a chart actually plots, with its canonical scale. */
function series(chart: RenderedChart): {
  column: string;
  unit: string;
  points: { label: string; value: number; display: string; rowId: string }[];
} | null {
  const column = chart.y_columns?.[0];
  if (!column) return null;
  const points = (chart.points ?? [])
    .map((p: ChartPoint) => ({
      rowId: p.row_id,
      label: text(p.label),
      value: numeric(p.values?.[column]),
      display: text(p.display?.[column]),
    }))
    .filter((p): p is { rowId: string; label: string; value: number;
                        display: string } => p.value !== null);
  if (!points.length) return null;
  return {
    column,
    unit: chart.series_units?.[column] ?? chart.unit ?? "",
    points,
  };
}

/**
 * A horizontal bar per category. §13: the shape for a ranked comparison,
 * because the labels are words and words read horizontally.
 */
//: The label column of every horizontal form. Shared so the ruler under
//: the bars lands exactly on the track rather than approximately on it.
const BAR_GRID = "minmax(0,11rem) 1fr auto";

function BarChart({ chart }: { chart: RenderedChart }) {
  const data = series(chart);
  if (!data) return null;
  // Scaled from canonical values, and from zero: a bar chart whose axis
  // starts elsewhere makes a 3% difference look like a threefold one.
  // The extent is the SERVER'S when it published one, which is what makes
  // the ruler below and the bars above the same scale.
  const { high } = scaleOf(chart, data.points.map((p) => p.value), true);
  const max = Math.max(high, 0);
  return (
    <div>
    <ol data-testid="v4-chart-bars" className="space-y-1.5">
      {data.points.map((point) => {
        const width = max > 0 ? (Math.abs(point.value) / max) * 100 : 0;
        return (
          <li key={point.rowId} className="grid grid-cols-[minmax(0,11rem)_1fr_auto] items-center gap-3">
            <span className="truncate text-xs text-text-secondary" dir="auto"
                  title={point.label}>
              {point.label}
            </span>
            <span className="h-4 rounded-sm bg-surface-sunken">
              <span
                data-testid="v4-chart-bar"
                data-value={String(point.value)}
                className="block h-4 rounded-sm bg-chart-1"
                style={{ width: `${width}%` }}
                title={`${point.label}: ${point.display}`}
              />
            </span>
            <span className="shrink-0 tabular-nums text-xs text-text-secondary">
              {point.display}
            </span>
          </li>
        );
      })}
    </ol>
    <Ruler axis={chart.y_axis} template={BAR_GRID} low={0} high={max} />
    <AxisCaption axis={chart.y_axis} />
    </div>
  );
}

/**
 * A line over an ordered axis. §13: the shape for a time series.
 *
 * FOUR FORMS SHARE THIS GEOMETRY and none of them is the others. A `line`
 * interpolates between readings; a `step_line` holds each value until the
 * next one, which is what a policy rate or a limit actually does; an `area`
 * fills to the baseline, so the eye reads the total rather than the slope;
 * a `scatter` draws the points and NO line, because there is no ordering
 * between them to interpolate along. All four rendered as a plain line,
 * which told the reader three things that were not true.
 */
function LineChart({ chart, variant = "line" }: {
  chart: RenderedChart;
  variant?: "line" | "step_line" | "area" | "scatter";
}) {
  const data = series(chart);
  const all = data?.points ?? [];
  const [view, setView] = useWindow(all.length);
  if (!data || all.length < 2) return null;

  // ZOOM IS A WINDOW OVER THE POINTS, never a re-scale of the values. The
  // marks shown are a subset of the published ones; none of them moves.
  const points = slice(all, view);
  const { low, high, span } = scaleOf(chart, points.map((p) => p.value), false);
  const at = (value: number, index: number): [number, number] => [
    xOf(index, points.length, PLOT_BOX),
    yOf(value, low, high, PLOT_BOX),
  ];
  const path = points
    .map((p, i) => {
      const [x, y] = at(p.value, i);
      if (i === 0) return `M ${px(x)} ${px(y)}`;
      if (variant === "step_line") {
        const [, previous] = at(points[i - 1].value, i - 1);
        return `L ${px(x)} ${px(previous)} L ${px(x)} ${px(y)}`;
      }
      return `L ${px(x)} ${px(y)}`;
    })
    .join(" ");
  const floor = yOf(Math.max(low, Math.min(0, high)), low, high, PLOT_BOX);

  return (
    <Plot
      testId={`v4-chart-${variant}`}
      title={chart.title}
      xAxis={chart.x_axis}
      yAxis={chart.y_axis}
      labels={points.map((p) => p.label)}
      low={low}
      high={high}
      zoom={{ count: all.length, window: view, onChange: setView }}
      hover={(index) => {
        const point = points[index];
        if (!point) return null;
        return {
          label: point.label,
          rowId: point.rowId,
          // The server's string for this exact point. Not read off the
          // chart, not recomputed from the geometry.
          values: [{ name: data.column, display: point.display, slot: 0 }],
        };
      }}
    >
      {variant === "area" ? (
        <path
          d={`${path} L ${PLOT_BOX.right} ${floor} L ${PLOT_BOX.left} ${floor} Z`}
          fill={slotColor(0)}
          fillOpacity="0.15"
          stroke="none"
        />
      ) : null}
      {variant === "scatter" ? null : (
        <path d={path} fill="none" stroke={slotColor(0)} strokeWidth="1.6"
              vectorEffect="non-scaling-stroke" strokeLinejoin="round" />
      )}
      {/* A mark on every point, on every variant. A line with no marks
          leaves a reader guessing where the observations actually are,
          and gives the hover layer nothing to sit under. */}
      {points.map((p, i) => {
        const [x, y] = at(p.value, i);
        return (
          <circle key={p.rowId} cx={x} cy={y}
                  r={variant === "scatter" ? 2.6 : 1.9}
                  fill={slotColor(0)}
                  data-testid={variant === "scatter"
                    ? "v4-chart-point" : "v4-chart-line-point"}
                  data-value={String(p.value)}>
            <title>{`${p.label}: ${p.display}`}</title>
          </circle>
        );
      })}
    </Plot>
  );
}

/** One bar per category, segmented by series. §13: the shape for a mix. */
/**
 * Segments piled to a total, per category.
 *
 * `normalise` is the difference between the two forms a credit pack uses.
 * A 100% stack answers "what SHARE sits in each bucket" — the delinquency
 * band mix — and every row fills the width. A plain stack keeps the totals
 * comparable, so a book that grew shows a longer bar.
 */
function StackedBarChart({ chart, normalise = true }: {
  chart: RenderedChart;
  normalise?: boolean;
}) {
  const columns = chart.y_columns ?? [];
  const points = chart.points ?? [];
  if (columns.length < 2 || !points.length) return null;
  // A STACK IS READ OFF ITS TOTAL, so the scale reaches the tallest BAR
  // rather than the tallest segment.
  const totals = points.map((p) =>
    columns.reduce((sum, c) => sum + Math.abs(numeric(p.values?.[c]) ?? 0), 0));
  const widest = scaleOf(chart, totals, true).high || 1;
  return (
    <div data-testid={normalise ? "v4-chart-stacked" : "v4-chart-stacked-abs"}
         className="space-y-2">
      <ol className="space-y-1.5">
        {points.map((point) => {
          const parts = columns.map((c) => numeric(point.values?.[c]) ?? 0);
          const sum = parts.reduce((a, b) => a + Math.abs(b), 0) || 1;
          const total = normalise ? sum : widest;
          return (
            <li key={point.row_id}
                className="grid grid-cols-[minmax(0,11rem)_1fr] items-center gap-3">
              <span className="truncate text-xs text-text-secondary" dir="auto">
                {text(point.label)}
              </span>
              <span className="flex h-4 overflow-hidden rounded-sm bg-surface-sunken">
                {parts.map((value, index) => (
                  <span
                    key={columns[index]}
                    className="h-4"
                    // BY SLOT, NEVER BY RANK: a series keeps its colour
                    // whatever else is on screen beside it.
                    style={{ width: `${(Math.abs(value) / total) * 100}%`,
                             backgroundColor: slotColor(index) }}
                    title={`${columns[index]}: ${
                      text(point.display?.[columns[index]])}`}
                  />
                ))}
              </span>
            </li>
          );
        })}
      </ol>
      {/* A 100% stack is read as a share of the row, so the absolute
          scale underneath it would be a second, wrong story. */}
      {normalise ? null : (
        <Ruler axis={chart.y_axis} template="minmax(0,11rem) 1fr"
               low={0} high={widest} />
      )}
      {normalise ? null : <AxisCaption axis={chart.y_axis} />}
      <Legend names={columns} />
    </div>
  );
}

/** Bars side by side per category: the comparison is WITHIN a group. */
function GroupedBarChart({ chart }: { chart: RenderedChart }) {
  const columns = chart.y_columns ?? [];
  const points = chart.points ?? [];
  if (columns.length < 2 || !points.length) return null;
  const max = scaleOf(
    chart,
    points.flatMap((p) => columns.map((c) => numeric(p.values?.[c]) ?? 0)),
    true).high || 1;
  return (
    <div data-testid="v4-chart-grouped" className="space-y-2">
      <ol className="space-y-2">
        {points.map((point) => (
          <li key={point.row_id} className="space-y-0.5">
            <span className="truncate text-xs text-text-secondary" dir="auto">
              {text(point.label)}
            </span>
            {columns.map((column, index) => {
              const value = numeric(point.values?.[column]) ?? 0;
              return (
                <span key={column} className="flex items-center gap-2">
                  <span className="h-2.5 w-full rounded-sm bg-surface-sunken">
                    <span className="block h-2.5 rounded-sm"
                          style={{ width: `${(Math.abs(value) / max) * 100}%`,
                                   backgroundColor: slotColor(index) }}
                          title={`${column}: ${text(point.display?.[column])}`} />
                  </span>
                  <span className="shrink-0 tabular-nums text-[10px] text-text-muted">
                    {text(point.display?.[column])}
                  </span>
                </span>
              );
            })}
          </li>
        ))}
      </ol>
      <Ruler axis={chart.y_axis} template="1fr auto" low={0} high={max} />
      <AxisCaption axis={chart.y_axis} />
      <Legend names={columns} />
    </div>
  );
}

/**
 * Volumes as bars, a RATE as a line on its own scale.
 *
 * Exposure in SAR millions and a delinquency rate in percent do not share
 * an axis. Plotted on one, the rate is a flat line along the floor and the
 * chart says nothing — which is why this form exists separately.
 */
function ComboChart({ chart }: { chart: RenderedChart }) {
  const columns = chart.y_columns ?? [];
  const points = chart.points ?? [];
  if (columns.length < 2 || !points.length) return null;
  const [bars, line] = columns;
  const barMax = extentOf(chart.y_axis,
                          points.map((p) => numeric(p.values?.[bars]) ?? 0),
                          { zeroBased: true })[1] || 1;
  const rates = points.map((p) => numeric(p.values?.[line]) ?? 0);
  // THE SECOND SCALE, published separately. A combo is the one form this
  // product draws on two, because a rate over the volumes it is a rate of
  // is what it is for -- and both have to be named or the reader cannot
  // tell which mark belongs to which.
  const [bottom, top] = extentOf(chart.y_axis_secondary, rates);
  const span = top - bottom || 1;
  return (
    <div data-testid="v4-chart-combo" className="space-y-2">
      <ol className="space-y-1.5">
        {points.map((point, index) => {
          const value = numeric(point.values?.[bars]) ?? 0;
          const rate = rates[index];
          return (
            <li key={point.row_id}
                className="grid grid-cols-[minmax(0,9rem)_1fr_auto] items-center gap-3">
              <span className="truncate text-xs text-text-secondary" dir="auto">
                {text(point.label)}
              </span>
              <span className="relative block h-4 rounded-sm bg-surface-sunken">
                <span className="block h-4 rounded-sm bg-chart-1"
                      style={{ width: `${(Math.abs(value) / barMax) * 100}%` }}
                      title={`${bars}: ${text(point.display?.[bars])}`} />
                <span data-testid="v4-combo-rate"
                      className="absolute top-0 h-4 w-0.5 bg-warning"
                      style={{ left: `${((rate - bottom) / span) * 100}%` }}
                      title={`${line}: ${text(point.display?.[line])}`} />
              </span>
              <span className="shrink-0 tabular-nums text-xs text-warning">
                {text(point.display?.[line])}
              </span>
            </li>
          );
        })}
      </ol>
      <Ruler axis={chart.y_axis} template="minmax(0,9rem) 1fr auto"
             low={0} high={barMax} />
      <AxisCaption axis={chart.y_axis} />
      {chart.y_axis_secondary?.label ? (
        <p className="mt-0.5 text-center text-xs text-warning">
          {chart.y_axis_secondary.label}
          {chart.y_axis_secondary.ticks.length ? (
            <span className="ml-2 tabular-nums text-text-muted">
              {chart.y_axis_secondary.ticks[0].display}
              {" – "}
              {chart.y_axis_secondary.ticks[
                chart.y_axis_secondary.ticks.length - 1].display}
            </span>
          ) : null}
        </p>
      ) : null}
    </div>
  );
}

/** Shares of one whole. `hole` makes it a donut. */
function SliceChart({ chart, hole }: { chart: RenderedChart; hole: number }) {
  const data = series(chart);
  if (!data) return null;
  const total = data.points.reduce((a, p) => a + Math.abs(p.value), 0);
  if (total <= 0) return null;
  const tones = ["var(--ipm-chart-1)", "var(--ipm-chart-2)", "var(--ipm-chart-3)",
                 "var(--ipm-chart-4)", "var(--ipm-chart-5)", "var(--ipm-chart-6)",
                 "var(--ipm-chart-7)", "var(--ipm-chart-8)"];
  // The running angle is carried in the array rather than in a variable
  // this closure reassigns: a render body that mutates its own scope is a
  // render that can disagree with itself on a re-run.
  const starts = data.points.reduce<number[]>(
    (acc, point) => [...acc,
                     acc[acc.length - 1] + (Math.abs(point.value) / total) * 360],
    [-90]);
  const arcs = data.points.map((point, index) => {
    const sweep = (Math.abs(point.value) / total) * 360;
    const start = starts[index];
    const angle = starts[index + 1];
    const rad = (deg: number) => (deg * Math.PI) / 180;
    const x1 = 60 + 52 * Math.cos(rad(start));
    const y1 = 60 + 52 * Math.sin(rad(start));
    const x2 = 60 + 52 * Math.cos(rad(angle));
    const y2 = 60 + 52 * Math.sin(rad(angle));
    return (
      <path key={point.rowId}
            d={`M 60 60 L ${px(x1)} ${px(y1)} A 52 52 0 ${
              sweep > 180 ? 1 : 0} 1 ${px(x2)} ${px(y2)} Z`}
            fill={tones[index % tones.length]}>
        <title>{`${point.label}: ${point.display}`}</title>
      </path>
    );
  });
  return (
    <div data-testid={hole > 0 ? "v4-chart-donut" : "v4-chart-pie"}
         className="flex flex-wrap items-center gap-4">
      <svg viewBox="0 0 120 120" className="h-32 w-32" role="img">
        {arcs}
        {hole > 0 ? (
          <circle cx="60" cy="60" r={52 * hole} fill="var(--ipm-surface)" />
        ) : null}
      </svg>
      <ul className="space-y-1 text-xs text-text-secondary">
        {data.points.map((point, index) => (
          <li key={point.rowId} className="flex items-center gap-1.5">
            <span className="inline-block h-2 w-2 rounded-sm"
                  style={{ backgroundColor: tones[index % tones.length] }} />
            <span className="truncate" dir="auto">{point.label}</span>
            <span className="tabular-nums text-text-muted">{point.display}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * Counts per band, drawn touching.
 *
 * The gap between bars is what says "these categories are separate". A DPD
 * distribution has no gaps — 10-19 abuts 20-29 — and drawing one invites a
 * reader to see groups that are not there.
 */
function HistogramChart({ chart }: { chart: RenderedChart }) {
  const data = series(chart);
  if (!data) return null;
  const points = data.points;
  const { low, high } = scaleOf(chart, points.map((p) => p.value), true);
  const base = yOf(Math.max(low, 0), low, high, PLOT_BOX);
  return (
    <Plot
      testId="v4-chart-histogram"
      title={chart.title}
      xAxis={chart.x_axis}
      yAxis={chart.y_axis}
      labels={points.map((p) => p.label)}
      banded
      low={low}
      high={high}
      hover={(index) => {
        const point = points[index];
        if (!point) return null;
        return {
          label: point.label,
          rowId: point.rowId,
          values: [{ name: data.column, display: point.display, slot: 0 }],
        };
      }}
    >
      {points.map((point, index) => {
        const { centre, width } = bandOf(index, points.length, PLOT_BOX);
        const y = yOf(point.value, low, high, PLOT_BOX);
        return (
          <rect
            key={point.rowId}
            data-testid="v4-histogram-bin"
            data-value={String(point.value)}
            // Drawn TOUCHING: the gap between bars is what says "these
            // categories are separate", and a DPD distribution has none --
            // 10-19 abuts 20-29.
            x={centre - width / 2}
            y={Math.min(y, base)}
            width={Math.max(0.5, width - 0.4)}
            height={Math.max(0.5, Math.abs(base - y))}
            fill={slotColor(0)}
          >
            <title>{`${point.label}: ${point.display}`}</title>
          </rect>
        );
      })}
    </Plot>
  );
}

/**
 * A bridge: each step starts where the last one finished.
 *
 * A waterfall is how a book explains a MOVEMENT — opening balance, new
 * lending, repayments, write-offs, closing balance. Drawn as ordinary bars
 * it becomes five unrelated quantities and the arithmetic that connects
 * them is invisible, which is exactly what `waterfall` did for the months
 * it was legal in the contract and fell through to `_bar_svg`.
 *
 * The last point is treated as a total and drawn from the baseline when it
 * equals the running sum; every other step floats.
 */
function WaterfallChart({ chart }: { chart: RenderedChart }) {
  const data = series(chart);
  if (!data) return null;
  // Running totals in an array, not a reassigned variable: the lint rule
  // that forbids the second one is right that a render body which mutates
  // its own scope can disagree with itself on a re-run.
  const cumulative = data.points.reduce<number[]>(
    (acc, point) => [...acc, acc[acc.length - 1] + point.value], [0]);
  const last = data.points[data.points.length - 1];
  // A LAST STEP THAT EQUALS EVERYTHING BEFORE IT IS THE TOTAL, not another
  // movement: "closing balance" is drawn from the baseline, or the bridge
  // ends with a bar that says the book doubled.
  const before = cumulative[cumulative.length - 2];
  const isTotal = Math.abs(before - last.value)
    <= Math.abs(last.value) * 1e-9;
  const steps = data.points.map((point, index) => (
    isTotal && index === data.points.length - 1
      ? { ...point, from: 0, to: point.value }
      : { ...point, from: cumulative[index], to: cumulative[index + 1] }));
  // A bridge is measured against the RUNNING TOTALS it passes through,
  // not against its individual movements.
  const reach = steps.flatMap((s) => [s.from, s.to]);
  const [floor, ceiling] = extentOf(chart.y_axis, reach, { zeroBased: true });
  const span = ceiling - floor || 1;
  return (
    <div>
    <ol data-testid="v4-chart-waterfall" className="space-y-1.5">
      {steps.map((step, index) => {
        const low = Math.min(step.from, step.to);
        const high = Math.max(step.from, step.to);
        const total = isTotal && index === steps.length - 1;
        return (
          <li key={step.rowId}
              className="grid grid-cols-[minmax(0,11rem)_1fr_auto] items-center gap-3">
            <span className="truncate text-xs text-text-secondary" dir="auto"
                  title={step.label}>{step.label}</span>
            <span className="relative block h-4 rounded-sm bg-surface-sunken">
              <span
                data-testid="v4-chart-waterfall-step"
                data-value={String(step.value)}
                className={`absolute h-4 rounded-sm ${
                  total ? "bg-text-secondary"
                        : step.value >= 0 ? "bg-positive" : "bg-negative"}`}
                style={{ left: `${((low - floor) / span) * 100}%`,
                         width: `${Math.max((high - low) / span, 0.004) * 100}%` }}
                title={`${step.label}: ${step.display}`}
              />
            </span>
            <span className="shrink-0 tabular-nums text-xs text-text-secondary">
              {step.display}
            </span>
          </li>
        );
      })}
    </ol>
    <Ruler axis={chart.y_axis} template={BAR_GRID} low={floor} high={ceiling} />
    <AxisCaption axis={chart.y_axis} />
    </div>
  );
}

/**
 * Two measures and a third in the size of the mark.
 *
 * The form a concentration slide uses: exposure against delinquency rate,
 * with the bubble sized by account count, so a terrible rate over eleven
 * accounts does not read like a terrible rate over eleven thousand. Three
 * numbers per point is the whole reason to draw it, and it was rendering
 * as bars of the first one.
 */
function BubbleChart({ chart }: { chart: RenderedChart }) {
  const columns = chart.y_columns ?? [];
  const points = chart.points ?? [];
  if (columns.length < 2 || !points.length) return null;
  const [xColumn, yColumn, sizeColumn] = columns;
  const read = (column: string | undefined) => (column
    ? points.map((p) => numeric(p.values?.[column]) ?? 0) : []);
  const xs = read(xColumn);
  const ys = read(yColumn);
  const sizes = sizeColumn ? read(sizeColumn) : ys.map(() => 1);
  // Both scales from the server, so the bubble sitting against a tick on
  // screen sits against the same tick in the exported copy.
  const [xLow, xHigh] = extentOf(chart.x_axis, xs);
  const [yLow, yHigh] = extentOf(chart.y_axis, ys);
  const across = (value: number) =>
    PLOT_BOX.left
    + ((value - xLow) / ((xHigh - xLow) || 1)) * (PLOT_BOX.right - PLOT_BOX.left);
  const widest = Math.max(...sizes.map(Math.abs), 0) || 1;
  return (
    <Plot
      testId="v4-chart-bubble"
      title={chart.title}
      xAxis={chart.x_axis}
      yAxis={chart.y_axis}
      labels={points.map((p) => text(p.label))}
      low={yLow}
      high={yHigh}
      hover={(index) => hoverOf(points[index], columns)}
      footer={
        <p className="text-xs text-text-muted">
          {sizeColumn ? `Sized by ${sizeColumn}` : ""}
        </p>
      }
    >
      {points.map((point, index) => (
        <circle
          key={point.row_id}
          data-testid="v4-chart-bubble-mark"
          cx={across(xs[index])}
          cy={yOf(ys[index], yLow, yHigh, PLOT_BOX)}
          // AREA, not radius: a radius proportional to the value
          // exaggerates a big bubble by its square.
          r={2 + Math.sqrt(Math.abs(sizes[index]) / widest) * 9}
          fill={slotColor(0)}
          fillOpacity="0.45"
          stroke={slotColor(0)}
          strokeWidth="0.6"
        >
          <title>{`${text(point.label)}: ${
            columns.map((c) => text(point.display?.[c])).join(" / ")}`}</title>
        </circle>
      ))}
    </Plot>
  );
}

/**
 * A from/to result as a grid.
 *
 * NOT `analytics/charts.tsx#MatrixHeatmap`, which looks like the same
 * component and is not: it is hard-coded for row PERCENTAGES
 * (a hard-coded one-decimal round and a `%` tooltip), so a migration
 * counted in borrowers
 * renders as "100.0" and claims to be a percentage. It also formats in the
 * browser, which is the one thing the numeric contract forbids; takes a
 * single `categories` axis, so a sector-by-stage grid cannot be drawn; and
 * reads a missing cell as `?? 0`, asserting that nobody made a move the
 * query simply never reported.
 *
 * Every string here is the server's. The only arithmetic is the shade.
 */
function MatrixChart({ chart }: { chart: RenderedChart }) {
  const matrix = chart.matrix;
  if (!matrix?.rows?.length || !matrix.columns?.length) return null;
  const magnitudes = Object.values(matrix.cells ?? {})
    .filter((v): v is number => typeof v === "number")
    .map(Math.abs);
  const max = magnitudes.length ? Math.max(...magnitudes) : 0;

  return (
    <div data-testid="v4-chart-matrix" className="overflow-x-auto">
      <table className="border-separate border-spacing-0.5 text-xs">
        <thead>
          <tr>
            <th className="px-2 py-1 text-left text-[10px] font-semibold uppercase tracking-wide text-text-muted">
              {matrix.row_axis} \ {matrix.column_axis}
            </th>
            {matrix.columns.map((column) => (
              <th key={column}
                  className="px-1.5 py-1 text-center text-[10px] font-semibold text-text-muted">
                {column}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {matrix.rows.map((row) => (
            <tr key={row}>
              <th className="px-2 py-1 text-left text-[10px] font-semibold text-text-muted">
                {row}
              </th>
              {matrix.columns.map((column) => {
                const key = `${row}|${column}`;
                const value = matrix.cells?.[key];
                const shown = matrix.display?.[key];
                const has = typeof value === "number";
                const weight = has && max > 0 ? Math.abs(value) / max : 0;
                const mix = ((0.08 + 0.84 * weight) * 100).toFixed(1); // not-a-published-figure: a colour-mix ratio
                const diagonal = matrix.square && row === column;
                return (
                  <td
                    key={column}
                    data-testid="v4-matrix-cell"
                    data-cell={key}
                    data-empty={has ? undefined : "true"}
                    title={has ? `${row} → ${column}: ${shown}` : undefined}
                    className={[
                      "min-w-12 rounded-[3px] px-1.5 py-1.5 text-center",
                      "tabular-nums",
                      weight > 0.55 ? "text-accent-contrast" : "text-text-secondary",
                      diagonal ? "ring-1 ring-inset ring-accent" : "",
                    ].join(" ")}
                    style={{
                      // The ramp is mixed from the theme's own accent and
                      // its own surface, so a hot cell is hot in every theme
                      // rather than near-black on near-black.
                      backgroundColor: has
                        ? `color-mix(in srgb, var(--ipm-accent) ${mix}%, var(--ipm-surface))`
                        : "var(--ipm-surface-sunken)",
                    }}
                  >
                    {/* An empty cell is not a zero. */}
                    {has ? shown : "·"}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** Min, Q1, median, Q3, max — the five numbers, as computed by the server. */
function BoxChart({ chart }: { chart: RenderedChart }) {
  const boxes = chart.boxes ?? [];
  if (!boxes.length) return null;
  const numbers = boxes
    .flatMap((b) => [Number(b.minimum), Number(b.maximum)])
    .filter((n) => Number.isFinite(n));
  if (!numbers.length) return null;
  const top = Math.max(...numbers);
  const bottom = Math.min(...numbers);
  const span = top - bottom || 1;
  const place = (raw: string) => ((Number(raw) - bottom) / span) * 100;

  return (
    <ol data-testid="v4-chart-boxes" className="space-y-2">
      {boxes.map((box) => {
        const q1 = place(box.q1);
        const q3 = place(box.q3);
        return (
          <li key={box.label || "all"}
              className="grid grid-cols-[minmax(0,9rem)_1fr_auto] items-center gap-3">
            <span className="truncate text-xs text-text-secondary" dir="auto"
                  title={box.label}>
              {box.label || "All"}
            </span>
            <span data-testid="v4-box" data-label={box.label}
                  className="relative block h-5">
              <span className="absolute top-1/2 h-px bg-border-strong"
                    style={{
                      left: `${place(box.minimum)}%`,
                      width: `${place(box.maximum) - place(box.minimum)}%`,
                    }} />
              <span className="absolute top-0 h-5 rounded-sm border border-chart-1 bg-chart-1/15"
                    style={{
                      left: `${Math.min(q1, q3)}%`,
                      width: `${Math.max(Math.abs(q3 - q1), 0.5)}%`,
                    }} />
              <span data-testid="v4-box-median"
                    className="absolute top-0 h-5 w-0.5 bg-chart-1"
                    style={{ left: `${place(box.median)}%` }}
                    title={`median ${box.display?.median ?? ""}`} />
            </span>
            <span className="shrink-0 tabular-nums text-xs text-text-secondary">
              {box.display?.median}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

/**
 * The form the analyst asked for, drawn as itself.
 *
 * THE KIND DECIDES, not the shape of the payload. This read
 * `y_columns.length > 1` FIRST, so any chart with two measures became a
 * stack whatever it said it was — a combo, a grouped comparison and a
 * bubble all rendered as stacked bars. The count of series is a fallback
 * for a kind nobody recognises, not a rule that outranks the contract.
 */
export const CHART_BODIES: Record<
  ChartKind,
  (chart: RenderedChart) => React.ReactElement | null
> = {
  heatmap: (chart) => <MatrixChart chart={chart} />,
  box: (chart) => <BoxChart chart={chart} />,
  line: (chart) => <LineChart chart={chart} />,
  step_line: (chart) => <LineChart chart={chart} variant="step_line" />,
  area: (chart) => <LineChart chart={chart} variant="area" />,
  scatter: (chart) => <LineChart chart={chart} variant="scatter" />,
  stacked_bar: (chart) => <StackedBarChart chart={chart} normalise={false} />,
  stacked_bar_100: (chart) => <StackedBarChart chart={chart} />,
  grouped_bar: (chart) => <GroupedBarChart chart={chart} />,
  combo: (chart) => <ComboChart chart={chart} />,
  pie: (chart) => <SliceChart chart={chart} hole={0} />,
  donut: (chart) => <SliceChart chart={chart} hole={0.55} />,
  histogram: (chart) => <HistogramChart chart={chart} />,
  bubble: (chart) => <BubbleChart chart={chart} />,
  waterfall: (chart) => <WaterfallChart chart={chart} />,
  bar: (chart) => <BarChart chart={chart} />,
};

export function ResultChart({ chart, runId, index }: {
  chart: RenderedChart;
  /** Absent in a preview, where there is no stored run to export from. */
  runId?: string;
  /** This chart's position in the ANSWER, which is what the API addresses. */
  index?: number;
}) {
  const draw = CHART_BODIES[chart.kind as ChartKind];
  const body = draw
    ? draw(chart)
    : (chart.y_columns ?? []).length > 1
      ? <StackedBarChart chart={chart} />
      : <BarChart chart={chart} />;
  if (!body) return null;
  const unit =
    chart.matrix?.unit ||
    chart.boxes?.[0]?.unit ||
    chart.unit ||
    Object.values(chart.series_units ?? {})[0] ||
    "";
  return (
    <figure data-testid="v4-result-chart" data-kind={chart.kind}
            className="min-w-0">
      <figcaption className="mb-2 flex items-center gap-2 text-sm font-medium text-text-primary">
        <span className="min-w-0 truncate">
          {chart.title}
          {unit ? (
            <span className="ml-2 font-normal text-text-muted">{unit}</span>
          ) : null}
        </span>
        {runId && index !== undefined ? (
          <span className="ml-auto shrink-0">
            <ChartDownload runId={runId} index={index} />
          </span>
        ) : null}
      </figcaption>
      {/* The analyst's one line about why this form rather than the table
          beside it. Shown only when they wrote one. */}
      {chart.why_this_chart ? (
        <p data-testid="v4-chart-reason"
           className="mb-2 text-xs text-text-muted" dir="auto">
          {chart.why_this_chart}
        </p>
      ) : null}
      {body}
    </figure>
  );
}

// ---- what to show -------------------------------------------------------

/**
 * Chart and table together, with a toggle only when both say something.
 *
 * §21: a disabled Chart button beside a table that could never be charted is
 * a control that exists to be refused. When only the table is useful, only
 * the table appears.
 */
export function Visuals({
  tables,
  charts,
  runId,
}: {
  tables: RenderedTable[];
  charts: RenderedChart[];
  /**
   * The run these figures belong to.
   *
   * Absent in a preview or a seeded card, where nothing has been stored
   * to export. A download button that 404s is worse than no button.
   */
  runId?: string;
}) {
  const { usefulCharts, usefulTables, chartIndices } = choose(tables, charts);
  if (!usefulCharts.length && !usefulTables.length) return null;

  // EVERY CHART, ONE AFTER ANOTHER, and the tables below them.
  //
  // This was one chart and one table, mutually exclusive behind a toggle.
  // Two things were wrong with it. An answer that draws a trend per product
  // showed one product, silently — the rest were computed, validated,
  // rendered and dropped a line before the screen. And a reader who wanted
  // the numbers under the picture had to give up the picture to get them,
  // which is not a choice anybody wants to make about their own result.
  // ONE FIGURE AT A TIME, BEHIND ITS OWN BOUNDARY.
  //
  // MEASURED DEFECT. `finalization.render_tables` publishes a table it could
  // not resolve to a stored artifact by passing the analyst's raw dict
  // through untouched -- no `row_id`, no `canonical`, no `display`. The cell
  // renderer reads `row.display[column]`, so the whole subtree threw
  // "Cannot read properties of undefined", and the nearest boundary is the
  // ROUTE's (`app/error.tsx`): the entire thread page was replaced by "This
  // page could not be loaded", taking every earlier turn and the composer
  // with it. A reader could not scroll back, could not read the answer that
  // HAD worked, and could not ask anything else.
  //
  // Wrapped per figure, a malformed table costs one <figure>. The boundary
  // is the one this codebase already has, whose own docstring describes this
  // exact job; `area` names which figure failed, the message is shown rather
  // than swallowed, and `componentDidCatch` still writes the stack to the
  // console. Nothing is guarded INSIDE the renderer: a blank cell would hide
  // a defect, and this is meant to show one.
  return (
    <div data-testid="v4-visuals" className="mt-4 space-y-5">
      {usefulCharts.map((chart, index) => (
        <ErrorBoundary key={`${chart.artifact_id}-${chart.kind}-${index}`}
                       area={chart.title ? `The chart "${chart.title}"`
                                         : "This chart"}>
          <ResultChart chart={chart} runId={runId}
                       index={chartIndices[index]} />
        </ErrorBoundary>
      ))}
      {usefulTables.map((table, index) => (
        <ErrorBoundary key={`${table.artifact_id}-${index}`}
                       area={table.title ? `The table "${table.title}"`
                                         : "This table"}>
          <ResultTable table={table} runId={runId} />
        </ErrorBoundary>
      ))}
    </div>
  );
}

"use client";

/**
 * A persisted Scenario Result, drawn on the universal decomposition contract.
 *
 * Selected scope and total book side by side on ONE scale, the same
 * component in the same colour and position in both, and the exact table
 * beneath listing every taxonomy component (N/A ones with their reason).
 * Clicking a bar highlights that component in both charts and in the table.
 * Nothing here computes a number: every value is the server's string.
 */

import * as React from "react";
import Link from "next/link";

import { ChartCard, type ChartData } from "@/components/viz/chart-card";
import { ExportPackage } from "@/components/workspace/export-package";
import { ShareButton } from "@/components/workspace/share-button";
import { distribution, pareto } from "@/lib/viz/advanced";
import { contributions } from "@/lib/viz/figures";
import { componentTable, identities, kpis, methodComparison, plotted, scopeEquivalence, sharedScale, stageBeforeAfter, waterfall, type Decomposition, type DecompositionScope } from "@/lib/viz/decomposition";
import { count, moneyCol, sar, sarDelta } from "@/lib/viz/format";
import { METHOD_LABEL } from "@/lib/workspace/method-labels";
import type { ScenarioResult } from "@/lib/workspace/runs";


export function ResultView({ result, actions }: { result: ScenarioResult; actions?: React.ReactNode }) {
  const b = result.body;
  const methods = Object.keys(b.decomposition);
  const [method, setMethod] = React.useState(methods[0] ?? "");
  const [compact, setCompact] = React.useState(false);
  const [highlight, setHighlight] = React.useState("");
  const d = b.decomposition[method];
  const context = { releaseId: b.release_id, period: b.period, source: `scenario_result ${result.object_id} v${result.version} · ${METHOD_LABEL[method] ?? method}` };
  const ran = b.methods.ran;
  const unavailable = Object.entries(b.methods.unavailable ?? {});
  const layered = b.baseline.mode === "PRIOR_SCENARIO";

  return (
    <section className="space-y-4" data-testid="whatif-result" data-result-id={result.object_id} data-methods-ran={ran.join(",")}>
      <header className="flex flex-wrap items-start gap-3 rounded-xl border border-border bg-surface p-3 text-xs">
        <div className="min-w-0 flex-1">
          <h3 className="text-base font-semibold">
            {b.scenario_name} <span className="text-text-muted">· result {result.object_id}</span>
          </h3>
          <p className="text-text-muted">
            {b.cohort.description} · release {b.release_id} ·{" "}
            <span data-testid="whatif-result-stage-policy" data-policy={b.stage_policy_requested ?? b.stage_policy}>
              stages {b.stage_policy_requested ?? b.stage_policy}
            </span>
          </p>
          <p data-testid="whatif-result-baseline" data-mode={b.baseline.mode}>
            Baseline:{" "}
            {layered ? (
              <>
                layered on{" "}
                {b.chain.map((c, i) => (
                  <span key={c.executed_run_id}>
                    {i > 0 && " → "}
                    <span className="font-semibold">{c.name}</span> ({c.executed_run_id})
                  </span>
                ))}
              </>
            ) : (
              <>original reported baseline {b.period}</>
            )}
          </p>
          <p className="font-mono text-[10px] text-text-muted">
            contract {b.contract_digest.slice(0, 16)} · execution {b.execution_digest.slice(0, 16)} · {b.evidence}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-1">
          {methods.map((m) => (
            <button
              key={m}
              type="button"
              onClick={() => setMethod(m)}
              aria-pressed={m === method}
              className={`rounded-md border px-2 py-1 ${m === method ? "border-accent bg-accent text-accent-contrast" : "border-border"}`}
              data-testid={`whatif-result-method-${m}`}
            >
              {METHOD_LABEL[m] ?? m}
            </button>
          ))}
          {actions}
          <ShareButton objectId={result.object_id} testId="whatif-result-share" />
          <ExportPackage objectId={result.object_id} scopeSelector={`[data-result-id="${result.object_id}"]`} testId="whatif-result-export" />
        </div>
      </header>

      {unavailable.length > 0 && (
        <ul className="rounded-lg border border-warning bg-surface p-2 text-xs" data-testid="whatif-result-unavailable">
          {unavailable.map(([m, why]) => (
            <li key={m}>
              <span className="font-semibold">{METHOD_LABEL[m] ?? m} not run:</span> {why}
            </li>
          ))}
        </ul>
      )}

      {b.notes.length > 0 && (
        <ul className="space-y-1 rounded-lg border border-border bg-surface-sunken p-2 text-xs" data-testid="whatif-result-notes">
          {b.notes.map((n, i) => (
            <li key={i} className={n.includes("SIGN_REVIEW") ? "font-semibold text-negative" : ""}>
              {n}
            </li>
          ))}
        </ul>
      )}

      {d && <DecompositionPanel d={d} compact={compact} setCompact={setCompact} highlight={highlight} setHighlight={setHighlight} context={context} />}

      {ran.length > 1 && (
        <ChartCard
          title="Method comparison"
          subtitle="Every method on the same confirmed scenario, cohort and baseline"
          testId="whatif-result-methods"
          context={context}
          {...methodComparison(b.results)}
          height={260}
          table={{
            columns: [
              { key: "label", label: "Method" },
              { key: "status", label: "Status" },
              moneyCol("baseline", "Baseline", Object.values(b.results) as unknown as Record<string, unknown>[]),
              moneyCol("scenario", "Scenario", Object.values(b.results) as unknown as Record<string, unknown>[]),
              moneyCol("change", "Change", Object.values(b.results) as unknown as Record<string, unknown>[]),
              { key: "reason", label: "Reason / limitations" },
            ],
            rows: Object.values(b.results).map((r) => ({ ...r, reason: [r.reason, ...r.limitations].filter(Boolean).join("; ") })),
          }}
          defaultShowData
        />
      )}

      <div className="grid gap-4 lg:grid-cols-2">
        {b.stages.length > 0 && (
          <ChartCard
            title="ECL by stage, before and after"
            subtitle={`Stages ${b.stage_policy_requested ?? b.stage_policy}: exposures keep their stage unless an approved rule moves them`}
            testId="whatif-result-stages"
            context={context}
            {...stageBeforeAfter(b.stages)}
            height={260}
            table={{
              columns: [
                { key: "stage", label: "Stage" },
                { key: "exposures", label: "Exposures", align: "right", format: (v) => count(Number(v)) },
                moneyCol("ecl_before", "ECL before", b.stages as unknown as Record<string, unknown>[]),
                moneyCol("ecl_after", "ECL after", b.stages as unknown as Record<string, unknown>[]),
                moneyCol("change", "Change", b.stages as unknown as Record<string, unknown>[]),
              ],
              rows: b.stages as unknown as Record<string, unknown>[],
            }}
          />
        )}
        {b.top_contributors.length > 0 && (
          <ChartCard
            title="Largest contributors"
            subtitle="Exposures with the largest Delta change"
            testId="whatif-result-top"
            context={context}
            {...contributions(
              b.top_contributors.map((t) => ({ label: `${t.entity_id} · ${t.group}`, value: Number(t.change) })),
              "SAR_mn",
              { dimension: "Exposure" },
            )}
            height={320}
            table={{
              columns: [
                { key: "entity_id", label: "Exposure" },
                { key: "owner_id", label: "Owner" },
                { key: "group", label: "Group" },
                { key: "stage", label: "Stage" },
                { key: "ecl_before", label: "ECL before", align: "right" },
                { key: "ecl_after", label: "ECL after", align: "right" },
                { key: "change", label: "Change", align: "right" },
              ],
              rows: b.top_contributors as unknown as Record<string, unknown>[],
            }}
          />
        )}
        {(b.pareto?.length ?? 0) > 0 && (
          <ChartCard
            title={`Delta change by ${b.pareto?.[0]?.dimension === "product" ? "product" : "sector"}, largest first`}
            subtitle="Bars: change in SAR; line: cumulative share of the selected-scope change"
            testId="whatif-result-pareto"
            context={context}
            {...pareto(b.pareto ?? [])}
            height={320}
            table={{
              columns: [
                { key: "group", label: "Segment" },
                { key: "change", label: "ECL change (SAR m, raw)", align: "right" },
                { key: "cumulative_share", label: "Cumulative share", align: "right" },
              ],
              rows: (b.pareto ?? []) as unknown as Record<string, unknown>[],
            }}
          />
        )}
        {(b.change_distribution?.length ?? 0) > 0 && (
          <ChartCard
            title="How the change is spread across exposures"
            subtitle="Exposures by the change in their own ECL (Delta); unmoved exposures are in the table"
            testId="whatif-result-distribution"
            context={context}
            {...distribution(b.change_distribution ?? [])}
            height={300}
            table={{
              columns: [
                { key: "label", label: "Band" },
                { key: "n", label: "Exposures", align: "right" },
                { key: "ead", label: "EAD (SAR m, raw)", align: "right" },
              ],
              rows: (b.change_distribution ?? []) as unknown as Record<string, unknown>[],
            }}
          />
        )}
      </div>
    </section>
  );
}

function scopeKpis(s: DecompositionScope, testId: string) {
  return (
    <dl className="grid grid-cols-3 gap-2 text-xs md:grid-cols-6" data-testid={testId}>
      {kpis(s).map((k) => (
        <div key={k.label} className="rounded border border-border bg-surface-sunken p-2" title={`raw ${k.raw}`}>
          <dt className="text-text-muted">{k.label}</dt>
          <dd className="font-semibold tabular" data-raw={k.raw}>
            {k.value}
          </dd>
        </div>
      ))}
    </dl>
  );
}

export function DecompositionPanel({
  d,
  compact,
  setCompact,
  highlight,
  setHighlight,
  context,
}: {
  d: Decomposition;
  compact: boolean;
  setCompact: (v: boolean) => void;
  highlight: string;
  setHighlight: (id: string) => void;
  context: { releaseId?: string; period?: string; source?: string };
}) {
  const scale = sharedScale(d);
  const checks = identities(d);
  const table = componentTable(d);
  // DECOMP21: one population -> one bridge, once the equality is proven.
  const eq = scopeEquivalence(d);
  const single = eq.proven;
  const hidden = d.scopes.selected.components.filter((c) => c.status === "N/A").length;
  const selCol = moneyCol("selected", "Selected scope", table as unknown as Record<string, unknown>[]);
  const totCol = moneyCol("total", "Total book", table as unknown as Record<string, unknown>[]);
  const tableData: ChartData = {
    columns: [
      { key: "label", label: "Component" },
      selCol,
      { key: "selected_status", label: "Status" },
      totCol,
      { key: "total_status", label: "Status" },
      ...(single ? [{ key: "identical", label: "Identical" }] : []),
      { key: "reason", label: "Reason / definition" },
    ],
    rows: table.map((r) => ({
      ...r,
      identical: r.selected === r.total && r.selected_status === r.total_status ? "✓ same population" : "✗ differs",
      reason: r.reason || r.definition,
    })),
  };
  const click = (p: { customdata?: unknown }) => {
    const id = Array.isArray(p.customdata) ? String(p.customdata[0]) : "";
    setHighlight(highlight === id ? "" : id);
  };
  const cross = d.cross_scope;
  return (
    <div className="space-y-3" data-testid="whatif-decomposition" data-method={d.method} data-reconciles={String(checks.selected && checks.total && checks.cross)} data-contract={d.contract_version} data-scope-equals-total={String(single)}>
      {single ? (
        <section className="space-y-2 rounded-lg border-2 border-accent bg-accent-muted p-3 text-xs" data-testid="whatif-scope-equivalence">
          <h4 className="text-sm font-semibold">Selected scope = Total book</h4>
          <p>
            The selected population is the entire active book ({d.scopes.selected.kpis.exposures.toLocaleString()} exposures), so there is no rest of book.
          </p>
          <ul className="list-disc pl-5 tabular">
            <li data-testid="whatif-equivalence-rest">
              Rest-of-book ECL delta = <b>{sarDelta(Number(cross.rest_of_book_delta))}</b> (zero by definition)
            </li>
            <li data-testid="whatif-equivalence-deltas">
              Selected-scope delta <b>{sarDelta(Number(cross.selected_delta))}</b> = total-book delta <b>{sarDelta(Number(cross.total_delta))}</b>
            </li>
            <li data-testid="whatif-equivalence-components" data-identical={eq.identical} data-components={eq.components}>
              {eq.identical} of {eq.components} components identical in both scopes; opening, closing and change identical
            </li>
          </ul>
          {scopeKpis(d.scopes.selected, "whatif-kpis-selected")}
        </section>
      ) : (
        <div className="grid gap-3 lg:grid-cols-2">
          <div className="space-y-2">
            <h4 className="text-sm font-semibold">Selected scope — {d.scopes.selected.label}</h4>
            {scopeKpis(d.scopes.selected, "whatif-kpis-selected")}
          </div>
          <div className="space-y-2">
            <h4 className="text-sm font-semibold">Total active book</h4>
            {scopeKpis(d.scopes.total, "whatif-kpis-total")}
          </div>
        </div>
      )}
      <p className="rounded-lg border border-border bg-surface p-2 text-xs tabular" data-testid="whatif-cross-scope" data-reconciles={String(cross.reconciles)}>
        Selected Δ <b>{sarDelta(Number(cross.selected_delta))}</b> + rest-of-book Δ <b>{sarDelta(Number(cross.rest_of_book_delta))}</b> = total-book Δ{" "}
        <b>{sarDelta(Number(cross.total_delta))}</b> {cross.reconciles ? "✓ reconciles" : "✗ DOES NOT RECONCILE"}
        {cross.selected_share_of_total_change_pct && <> · selected share {cross.selected_share_of_total_change_pct}%</>}
        <span className="block text-text-muted">{cross.rest_of_book_reason}</span>
      </p>
      <label className="flex items-center gap-2 text-xs">
        <input type="checkbox" checked={compact} onChange={(e) => setCompact(e.target.checked)} data-testid="whatif-decomp-compact" />
        Compact chart: hide the {hidden} N/A components (the table always lists all {table.length})
      </label>
      <div className={single ? "grid gap-4" : "grid gap-4 xl:grid-cols-2"}>
        {(single ? (["selected"] as const) : (["selected", "total"] as const)).map((name) => {
          const s = d.scopes[name];
          const fig = waterfall(s, { compact, highlight, scale });
          return (
            <ChartCard
              key={name}
              title={single ? "ECL bridge — Selected scope = Total book" : name === "selected" ? "ECL bridge — selected scope" : "ECL bridge — total active book"}
              subtitle={`${s.identity} · ${s.reconciles ? "reconciles" : "DOES NOT RECONCILE"} · residual ${s.residual}`}
              testId={`whatif-waterfall-${name}`}
              context={context}
              data={fig.data}
              layout={fig.layout}
              height={380}
              onPointClick={click}
              table={{
                columns: [
                  { key: "label", label: "Component" },
                  moneyCol("value", "Value", plotted(s, compact) as unknown as Record<string, unknown>[]),
                  { key: "status", label: "Status" },
                  { key: "reason", label: "Reason" },
                ],
                rows: plotted(s, compact).map((c) => ({ label: c.label, value: c.value ?? "", status: c.status, reason: c.reason })),
              }}
            />
          );
        })}
      </div>
      <div className="overflow-auto rounded-lg border border-border" data-testid="whatif-decomp-table">
        <table className="w-full text-xs">
          <thead className="bg-surface-sunken">
            <tr>
              {tableData.columns.map((c) => (
                <th key={c.key + c.label} className={`px-2 py-1 ${c.align === "right" ? "text-right" : "text-left"}`}>
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {table.map((r) => (
              <tr
                key={r.id}
                data-component={r.id}
                data-selected={r.selected}
                data-total={r.total}
                data-status={r.selected_status}
                className={`border-t border-border ${highlight === r.id ? "bg-accent/10 font-semibold" : ""}`}
                onClick={() => setHighlight(highlight === r.id ? "" : r.id)}
              >
                <td className="px-2 py-1">
                  <span className="mr-1 inline-block h-2.5 w-2.5 rounded-sm align-middle" style={{ background: r.colour }} aria-hidden />
                  {r.label}
                </td>
                <td className="px-2 py-1 text-right tabular" title={r.selected}>
                  {r.selected_status === "N/A" ? "N/A" : selCol.format(r.selected)}
                </td>
                <td className="px-2 py-1">{r.selected_status}</td>
                <td className="px-2 py-1 text-right tabular" title={r.total}>
                  {r.total_status === "N/A" ? "N/A" : totCol.format(r.total)}
                </td>
                <td className="px-2 py-1">{r.total_status}</td>
                {single && (
                  <td className="px-2 py-1" data-testid="whatif-decomp-identical">
                    {r.selected === r.total && r.selected_status === r.total_status ? "✓ same population" : "✗ differs"}
                  </td>
                )}
                <td className="px-2 py-1 text-text-muted">{r.reason || r.definition}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export function ResultLink({ resultId }: { resultId: string }) {
  return (
    <Link href={`/what-if/result/${resultId}`} className="text-accent underline" data-testid="whatif-result-link">
      Open result {resultId}
    </Link>
  );
}
